// Same test source compiled against original sealed kernels and the successor.
#include "surface_emission.hpp"
#include <bit>
#include <fstream>
#include <string>
#include <stdexcept>
namespace se=surface_emission;
int main(int argc,char**argv){if(argc!=2)return 2;std::ofstream out(argv[1],std::ios::binary);auto put=[&](auto x){out.write(reinterpret_cast<const char*>(&x),sizeof(x));};auto str=[&](std::string s){put(std::uint64_t(s.size()));out.write(s.data(),s.size());};auto ledger=[&](const se::Ledger&l){for(double x:{l.physical_electron_number,l.particle_charge_C,l.electrode_charge_C,l.wall_heat_J,l.outgoing_K_J,l.incoming_K_J,l.electron_reference_change_J,l.image_reference_change_J,l.resolved_matching_field_work_J})put(x);};
 auto packet=[&](const se::Packet&p){put(p.event_id);put(p.accepted_state);put(p.patch_id);put(p.weight);put(p.normal_metal_energy_eV);put(p.transverse_energy_eV);for(auto x:p.proper_velocity_m_s)put(x);ledger(p.ledger);};
 for(double T:{0.,300.,1500.,3000.})for(double F:{-1e8,0.,.5,1.,1e6,1e8,1e9})for(double phi:{3.5,4.3}){put(T);put(F);put(phi);try{se::Config cfg{phi,32,32,48};auto d=se::evaluate(T,F,cfg);put(std::uint8_t(1));for(double x:{d.current_A_m2,d.log_current_A_m2,d.mean_metal_energy_eV,d.wall_heat_W_m2,d.barrier_lowering_eV,d.fermi_decay_width_eV})put(x);put(d.has_log_current);put(d.current_underflow);put(std::uint64_t(d.nodes.size()));for(auto&n:d.nodes)for(double x:{n.normal_energy_eV,n.probability,n.cdf,n.mean_transverse_eV})put(x);
 if(!d.nodes.empty()){se::Stage s;s.accepted_state=s.field_accepted_state=s.thermal_accepted_state=s.mesh_revision=s.material_revision=s.patch_id=1;s.dt=1e-14;s.T_K=T;s.area_m2=1e-6;s.outward_normal={0,1,0};s.total_E={0,-F,0};s.material_temperature_phase_admitted=s.locally_planar_barrier_admitted=s.local_equilibrium_electron_supply_admitted=true;auto f=se::prepare(s,cfg);for(double u:{.1,.5,.9}){try{se::MatchingPlane p{F>0?se::PlaneKind::ExplicitSchottkyNordheimHandoff:se::PlaneKind::ThermalVacuumSurfaceStep,F>0?se::required_SN_matching_distance_m(d)*1.1:0,true,true,true};auto q=se::sample(f,p,1,u,.3,.7,1);put(std::uint8_t(2));packet(q);put(se::kinetic_energy_J(q.proper_velocity_m_s));se::LayerPolicy lp;lp.local_linear_vacuum_extent_m=25e-6;auto l=se::begin_layer(f,lp,1,u,.3,.7,2);put(std::uint8_t(3));packet(l.state.particle);for(auto x:l.state.position_from_surface_m)put(x);put(int(l.state.status));if(l.state.status==se::LayerStatus::Active){auto a=se::advance_layer(l.state,s,lp,1e-16);put(std::uint8_t(4));packet(a.state.particle);for(auto x:a.state.position_from_surface_m)put(x);put(int(a.state.status));put(a.substeps);for(double x:{a.exchange.wall_heat_J,a.exchange.particle_K_change_J,a.exchange.electron_reference_change_J,a.exchange.image_energy_change_J,a.exchange.field_work_J})put(x);}}catch(const std::exception&e){put(std::uint8_t(0));str(e.what());}}}
 }catch(const std::exception&e){put(std::uint8_t(0));str(e.what());}}
 return out?0:1;}
